/* Total provider rows -- used by the generator's own sanity check. */
#define TC_ROW_COUNT 28

/* Build the TOOL_CATEGORIES document. Fresh each call; caller owns. */
json_t *tool_categories_build(void) {
    json_t *root = json_object();
    for (const tc_cat_t *c = TC_CATS; c->key; c++) {
        char *err = NULL;
        json_t *fields = json_parse(c->fields, &err);
        if (err) { free(err); continue; }
        json_t *arr = json_array();
        for (const tc_row_t *r = TC_ROWS; r->row; r++) {
            if (strcmp(TC_ORDER[r->cat], c->key) != 0) continue;
            char *rerr = NULL;
            json_t *row = json_parse(r->row, &rerr);
            if (rerr) { free(rerr); continue; }
            json_append(arr, row);
        }
        json_set(fields, "providers", arr);
        json_set(root, c->key, fields);
    }
    return root;
}
